define(Color, color, {
  copy(channels) {
    return Object.assign(new this.constructor(), this, channels)
  },
  displayable() {
    return this.rgb().displayable()
  },
  hex: color_formatHex, // Deprecated! Use color.formatHex.
  formatHex: color_formatHex,
  formatHex8: color_formatHex8,
  formatHsl: color_formatHsl,
  formatRgb: color_formatRgb,
  toString: color_formatRgb,
})

function color_formatHex() {
  return this.rgb().formatHex()
}

function color_formatHex8() {
  return this.rgb().formatHex8()
}

function color_formatHsl() {
  return hslConvert(this).formatHsl()
}

function color_formatRgb() {
  return this.rgb().formatRgb()
}

export default function color(format) {
  var m, l
  format = (format + "").trim().toLowerCase()
  return (m = reHex.exec(format))
    ? ((l = m[1].length),
      (m = parseInt(m[1], 16)),
      l === 6
        ? rgbn(m) // #ff0000
        : l === 3
          ? new Rgb(
              ((m >> 8) & 0xf) | ((m >> 4) & 0xf0),
              ((m >> 4) & 0xf) | (m & 0xf0),
              ((m & 0xf) << 4) | (m & 0xf),
              1,
            ) // #f00
          : l === 8
            ? rgba(
                (m >> 24) & 0xff,
                (m >> 16) & 0xff,
                (m >> 8) & 0xff,
                (m & 0xff) / 0xff,
              ) // #ff000000
            : l === 4
              ? rgba(
                  ((m >> 12) & 0xf) | ((m >> 8) & 0xf0),
                  ((m >> 8) & 0xf) | ((m >> 4) & 0xf0),
                  ((m >> 4) & 0xf) | (m & 0xf0),
                  (((m & 0xf) << 4) | (m & 0xf)) / 0xff,
                ) // #f000
              : null) // invalid hex
    : (m = reRgbInteger.exec(format))
      ? new Rgb(m[1], m[2], m[3], 1) // rgb(255, 0, 0)
      : (m = reRgbPercent.exec(format))
        ? new Rgb((m[1] * 255) / 100, (m[2] * 255) / 100, (m[3] * 255) / 100, 1) // rgb(100%, 0%, 0%)
        : (m = reRgbaInteger.exec(format))
          ? rgba(m[1], m[2], m[3], m[4]) // rgba(255, 0, 0, 1)
          : (m = reRgbaPercent.exec(format))
            ? rgba(
                (m[1] * 255) / 100,
                (m[2] * 255) / 100,
                (m[3] * 255) / 100,
                m[4],
              ) // rgb(100%, 0%, 0%, 1)
            : (m = reHslPercent.exec(format))
              ? hsla(m[1], m[2] / 100, m[3] / 100, 1) // hsl(120, 50%, 50%)
              : (m = reHslaPercent.exec(format))
                ? hsla(m[1], m[2] / 100, m[3] / 100, m[4]) // hsla(120, 50%, 50%, 1)
                : named.hasOwnProperty(format)
                  ? rgbn(named[format]) // eslint-disable-line no-prototype-builtins
                  : format === "transparent"
                    ? new Rgb(NaN, NaN, NaN, 0)
                    : null
}

function rgbn(n) {
  return new Rgb((n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff, 1)
}

function rgba(r, g, b, a) {
  if (a <= 0) r = g = b = NaN
  return new Rgb(r, g, b, a)
}

export function rgbConvert(o) {
  if (!(o instanceof Color)) o = color(o)
  if (!o) return new Rgb()
  o = o.rgb()
  return new Rgb(o.r, o.g, o.b, o.opacity)
}

export function rgb(r, g, b, opacity) {
  return arguments.length === 1
    ? rgbConvert(r)
    : new Rgb(r, g, b, opacity == null ? 1 : opacity)
}

export function Rgb(r, g, b, opacity) {
  this.r = +r
  this.g = +g
  this.b = +b
  this.opacity = +opacity
}

define(
  Rgb,
  rgb,
  extend(Color, {
    brighter(k) {
      k = k == null ? brighter : Math.pow(brighter, k)
      return new Rgb(this.r * k, this.g * k, this.b * k, this.opacity)
    },
    darker(k) {
      k = k == null ? darker : Math.pow(darker, k)
      return new Rgb(this.r * k, this.g * k, this.b * k, this.opacity)
    },
    rgb() {
      return this
    },
    clamp() {
      return new Rgb(
        clampi(this.r),
        clampi(this.g),
        clampi(this.b),
        clampa(this.opacity),
      )
    },
    displayable() {
      return (
        -0.5 <= this.r &&
        this.r < 255.5 &&
        -0.5 <= this.g && this.g < 255.5 &&
        -0.5 <= this.b && this.b < 255.5 &&
        0 <= this.opacity && this.opacity <= 1
      )
    },
    hex: rgb_formatHex, // Deprecated! Use color.formatHex.
    formatHex: rgb_formatHex,
    formatHex8: rgb_formatHex8,
    formatRgb: rgb_formatRgb,
    toString: rgb_formatRgb,
  }),
)

function rgb_formatHex() {
  return `#${hex(this.r)}${hex(this.g)}${hex(this.b)}`
}

function rgb_formatHex8() {
  return `#${hex(this.r)}${hex(this.g)}${hex(this.b)}${hex((isNaN(this.opacity) ? 1 : this.opacity) * 255)}`
}

function rgb_formatRgb() {
  const a = clampa(this.opacity)
  return `${
    a === 1 ? "rgb(" : "rgba("
  }${clampi(this.r)}, ${clampi(this.g)}, ${clampi(this.b)}${
    a === 1 ? ")" : `, ${a})`
  }`
}

function clampa(opacity) {
  return isNaN(opacity) ? 1 : Math.max(0, Math.min(1, opacity))
}

function clampi(value) {
  return Math.max(0, Math.min(255, Math.round(value) || 0))
}

function hex(value) {
  value = clampi(value)
  return (value < 16 ? "0" : "") + value.toString(16)
}

function hsla(h, s, l, a) {
  if (a <= 0) h = s = l = NaN
  else if (l <= 0 || l >= 1) h = s = NaN
  else if (s <= 0) h = NaN
  return new Hsl(h, s, l, a)
}

export function hslConvert(o) {
  if (o instanceof Hsl) return new Hsl(o.h, o.s, o.l, o.opacity)
  if (!(o instanceof Color)) o = color(o)
  if (!o) return new Hsl()
  if (o instanceof Hsl) return o
  o = o.rgb()
  var r = o.r / 255,
    g = o.g / 255,
    b = o.b / 255,
    min = Math.min(r, g, b),
    max = Math.max(r, g, b),
    h = NaN,
    s = max - min,
    l = (max + min) / 2
  if (s) {
    if (r === max) h = (g - b) / s + (g < b) * 6
    else if (g === max) h = (b - r) / s + 2
    else h = (r - g) / s + 4
    s /= l < 0.5 ? max + min : 2 - max - min
    h *= 60
  } else {
    s = l > 0 && l < 1 ? 0 : h
  }
  return new Hsl(h, s, l, o.opacity)
}

export function hsl(h, s, l, opacity) {
  return arguments.length === 1
    ? hslConvert(h)
    : new Hsl(h, s, l, opacity == null ? 1 : opacity)
}

function Hsl(h, s, l, opacity) {
  this.h = +h
  this.s = +s
  this.l = +l
  this.opacity = +opacity
}

define(
  Hsl,
  hsl,
  extend(Color, {
    brighter(k) {
      k = k == null ? brighter : Math.pow(brighter, k)
      return new Hsl(this.h, this.s, this.l * k, this.opacity)
    },
    darker(k) {
      k = k == null ? darker : Math.pow(darker, k)
      return new Hsl(this.h, this.s, this.l * k, this.opacity)
    },
    rgb() {
      var h = (this.h % 360) + (this.h < 0) * 360,
        s = isNaN(h) || isNaN(this.s) ? 0 : this.s,
        l = this.l,
        m2 = l + (l < 0.5 ? l : 1 - l) * s,
        m1 = 2 * l - m2
      return new Rgb(
        hsl2rgb(h >= 240 ? h - 240 : h + 120, m1, m2),
        hsl2rgb(h, m1, m2),
        hsl2rgb(h < 120 ? h + 240 : h - 120, m1, m2),
        this.opacity,
      )
    },
    clamp() {
      return new Hsl(
        clamph(this.h),
        clampt(this.s),
        clampt(this.l),
        clampa(this.opacity),
      )
    },
    displayable() {
      return (
        ((0 <= this.s && this.s <= 1) || isNaN(this.s)) &&
        0 <= this.l && this.l <= 1 &&
        0 <= this.opacity && this.opacity <= 1
      )
    },
    formatHsl() {
      const a = clampa(this.opacity)
      return `${
        a === 1 ? "hsl(" : "hsla("
      }${clamph(this.h)}, ${clampt(this.s) * 100}%, ${clampt(this.l) * 100}%${
        a === 1 ? ")" : `, ${a})`
      }`
    },
  }),
)

function clamph(value) {
  value = (value || 0) % 360
  return value < 0 ? value + 360 : value
}

function clampt(value) {
  return Math.max(0, Math.min(1, value || 0))
}

/* From FvD 13.37, CSS Color Module Level 3 */
function hsl2rgb(h, m1, m2) {
  return (
    (h < 60
      ? m1 + ((m2 - m1) * h) / 60
      : h < 180
        ? m2
        : h < 240
          ? m1 + ((m2 - m1) * (240 - h)) / 60
          : m1) * 255
  )
}
