import { sqrt } from "../math.js"

export default {
  draw(context, size) {
    const r = sqrt(size / 5) / 2
    context.moveTo(-3 * r, -r)
    context.lineTo(-r, -r)
    context.lineTo(-r, -3 * r)
    context.lineTo(r, -3 * r)
    context.lineTo(r, -r)
    context.lineTo(3 * r, -r)
    context.lineTo(3 * r, r)
    context.lineTo(r, r)
    context.lineTo(r, 3 * r)
    context.lineTo(-r, 3 * r)
    context.lineTo(-r, r)
    context.lineTo(-3 * r, r)
    context.closePath()
  },
}
